import {PARTS,EXERCISES,PLANS,CARDIO_TYPES,createSession,createSet,summarizeSession,summarizeCardio,weeklySummary,localDateKey} from './domain.js';
import * as db from './db.js';
import {preparePhoto,recognizeWorkoutImage} from './photos.js';
import {normalizeProfile,validateAppBackup} from './validation.js';
import {getDailyCovers,mountCoverCarousel} from './cover-carousel.js';

const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const num=v=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:1}).format(Number(v)||0);
const paths={
 dumbbell:'<path d="m6 5-2 2m3-3 3 3m4 7 3 3m0 2 2-2M9 9l6 6M2 7l5-5m10 20 5-5M4 9l5-5m6 16 5-5"/>',
 home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',
 activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',
 calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h1m6 0h1"/>',
 play:'<path d="m9 5 11 7-11 7z"/><path d="M4 4v16"/>',
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
 left:'<path d="m14 6-6 6 6 6"/>',
 right:'<path d="m10 6 6 6-6 6"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',
 check:'<path d="m5 12 4 4L19 6"/>',
 close:'<path d="m6 6 12 12M6 18 18 6"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
 flame:'<path d="M12 3c1 5-4 5-3 10 1-1 2-2 3-4 1 3 4 4 4 7 0 3-2 5-5 5-5 0-8-5-6-9 0 2 1 3 2 3-1-6 3-7 5-12Z"/>',
 target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',
 settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m9 3-1 3-3 1-2 5 2 5 3 1 1 3h6l1-3 3-1 2-5-2-5-3-1-1-3Z"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
 book:'<path d="M3 4h6c2 0 3 1 3 2 0-1 1-2 3-2h6v16h-6c-2 0-3 1-3 1s-1-1-3-1H3zM12 6v15"/>',
 photo:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',
 scan:'<path d="M3 8V4a1 1 0 0 1 1-1h4m8 0h4a1 1 0 0 1 1 1v4m0 8v4a1 1 0 0 1-1 1h-4m-8 0H4a1 1 0 0 1-1-1v-4M3 12h18"/>',
 upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',
 download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',
 pause:'<path d="M8 5v14M16 5v14"/>',
 trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',
 link:'<path d="m9 15 6-6m-8 3-2 2a4 4 0 0 0 5 6l3-3m-2-10 3-3a4 4 0 0 1 6 5l-3 3"/>',
 copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
 person:'<circle cx="12" cy="7" r="3"/><path d="M5 21v-2a7 7 0 0 1 14 0v2"/>',
 phone:'<rect x="6" y="2" width="12" height="20" rx="3"/><path d="M10 18h4"/>',
 shield:'<path d="m12 2 8 3v7c0 4-3 7-8 10-5-3-8-6-8-10V5z"/><path d="m8 12 3 3 5-6"/>',
 bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-8z"/>',
 chart:'<path d="M4 3v18h17M8 17v-5m5 5V8m5 9V5"/>',
 legs:'<path d="M8 3h8l-1 8 3 9-4 1-3-8-2 8H5l2-10z"/>',
 shoulders:'<path d="M9 4h6l1 4 4 3 1 6-4 1-2-5H9l-2 5-4-1 1-6 4-3z"/>',
 back:'<path d="m7 4-4 4 2 6 4 2v5h6v-5l4-2 2-6-4-4-5 2zM12 8v9m-4-5 4 2 4-2"/>',
 chest:'<path d="m7 4-4 5 2 7 4 1 3-3 3 3 4-1 2-7-4-5-5 2zM12 7v7M6 11h3m6 0h3"/>',
 arms:'<path d="m8 3 4 1-2 6 3 2 3-3 4 3-2 6-6 3-8-4-1-5z"/>',
 core:'<path d="m8 3 4 2 4-2 3 6-3 12H8L5 9zM12 8v10m-4-7h8m-7 4h6"/>'
};
const icon=(name,cls='')=>`<svg viewBox="0 0 24 24" aria-hidden="true" class="${cls}">${paths[name]||paths.dumbbell}</svg>`;
const state={route:'home',profile:{name:'Cong',weight:70,weightConfirmed:false,weeklyGoal:3,restSeconds:90},sessions:[],favorites:[],active:null,part:'all',search:'',selected:new Set(),historyPeriod:'week',historyDay:null,calendar:new Date(),progressExercise:'',modalKind:'',photoUrls:new Map(),recognition:null,pendingBackup:null,saveError:false,offline:!navigator.onLine};
let saveTimer,toastTimer,saveQueue=Promise.resolve(),restNotified=false,editingId=null,currentRecordId=null;
let storageBusy=false,dataGeneration=0,recognitionJob=0,fileBusy=false,cardioContext=null,strengthContext=null,finishing=false,releaseWriteLock=null;
state.readOnly=false;
let coverCleanup=null;
const completed=()=>state.sessions.filter(s=>s.status==='completed');
const elapsed=s=>Math.max(0,Number(s?.elapsedSeconds||0)+(s?.runningSince?Math.floor((Date.now()-Number(s.runningSince))/1000):0));
const summary=s=>summarizeSession({...s,elapsedSeconds:s.status==='active'?elapsed(s):s.elapsedSeconds},state.profile);
const kcalValue=s=>{const v=summary(s);return !v.weightAssumed||state.profile.weightConfirmed?num(Math.round(v.totalKcal)):(s.cardio||[]).some(c=>!summarizeCardio(c,state.profile,s).estimated)?num(Math.round(v.recordedKcal)):'—';};
const timeString=n=>{const secs=Math.max(0,Math.floor(n));const h=Math.floor(secs/3600);return `${h?String(h).padStart(2,'0')+':':''}${String(Math.floor(secs/60)%60).padStart(2,'0')}:${String(secs%60).padStart(2,'0')}`;};
const dateLabel=d=>new Date(d).toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'short'});
const titleFor=s=>s.title||[...new Set((s.exercises||[]).filter(e=>e.sets.some(a=>a.done)).map(e=>PARTS.find(p=>p.id===e.part)?.label).filter(Boolean))].slice(0,2).join(' · ')||((s.cardio||[]).length?'有氧训练':'我的训练');
const getExercise=id=>EXERCISES.find(e=>e.id===id);
function releaseURL(key){const url=state.photoUrls.get(key);if(url)URL.revokeObjectURL(url);state.photoUrls.delete(key);}
function releasePhotoURLs(id){releaseURL(id+':thumb');releaseURL(id+':full');}
async function takeWriteLock(){if(!navigator.locks)return;await new Promise((resolve,reject)=>{navigator.locks.request('fitlog-single-writer',{ifAvailable:true},async lock=>{state.readOnly=!lock;resolve();if(lock)await new Promise(r=>{releaseWriteLock=r;});}).catch(reject);});}
async function replaceData(action){if(storageBusy||fileBusy)throw new Error('照片或数据正在保存，请完成后再试。');storageBusy=true;dataGeneration++;clearTimeout(saveTimer);const previous=state.active;state.active=null;try{await saveQueue.catch(()=>{});await action();await refreshData();}catch(error){state.active=previous;throw error;}finally{storageBusy=false;}}
const week=()=>weeklySummary(state.sessions,state.profile);
const today=()=>localDateKey();

function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3800);}
function closeModal(){if($('#modal').open)$('#modal').close();state.modalKind='';}
function modal(title,body,kind='generic'){
  $('#modal-body').innerHTML=`<div class="modal-title"><h2>${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="关闭">${icon('close')}</button></div>${body}`;
  state.modalKind=kind;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;
}
function navigate(route){closeModal();if(location.hash==='#'+route){state.route=route;render();}else location.hash=route;window.scrollTo({top:0,behavior:'instant'});}
function navHTML(){return [['home','home','今日训练'],['train','dumbbell','训练动作'],['history','calendar','训练日记'],['learn','play','教学收藏']].map(([route,i,label])=>`<a href="#${route}" class="nav-link ${state.route===route||(state.route==='workout'&&route==='train')?'active':''}" ${state.route===route?'aria-current="page"':''}>${icon(i)}<span>${label}</span></a>`).join('');}
function renderShell(){
  const brand=`<a class="brand" href="#home" aria-label="PingFit首页"><span class="brand-mark">${icon('dumbbell')}</span><strong class="ping-wordmark">Ping<span>Fit</span></strong></a>`;
  $('.sidebar').innerHTML=`${brand}<nav>${navHTML()}</nav><div class="nav-section">YOUR SPACE</div><button class="nav-link" data-action="settings">${icon('settings')}<span>个人设置</span></button><div class="sidebar-bottom"><div class="install-card"><div class="install-symbol">${icon('phone')}</div><h4>让训练，随手可及</h4><p>把PingFit添加到 iPhone 主屏幕<br>下次训练，一点就开始。</p><button data-action="install">添加到主屏幕 ${icon('arrow')}</button></div><button class="profile-button" data-action="settings"><span class="avatar">${esc(state.profile.name.slice(0,1))}</span><span><strong>${esc(state.profile.name)}</strong><small>我的训练空间</small></span>${icon('right')}</button></div>`;
  $('.bottom-nav').innerHTML=navHTML();
  const d=new Date(),hour=d.getHours(),greeting=hour<6?'夜深了':hour<12?'早上好':hour<18?'下午好':'晚上好';
  $('#app-header').innerHTML=`<div class="mobile-brand">${brand}<button class="icon-button" data-action="settings" aria-label="个人设置">${icon('person')}</button></div><div class="app-header"><div><div class="greeting-top">${esc(d.toLocaleDateString('en-US',{month:'short',day:'numeric',weekday:'short'}).toUpperCase())}</div><h1>${greeting}，${esc(state.profile.name)}<span class="green">.</span></h1><p class="greeting-sub">今天的每一份努力，都会留下痕迹。</p></div><div class="header-actions"><span class="local-badge"><i></i>数据保存在本机</span><button class="icon-button install-top" data-action="install" aria-label="安装到主屏幕">${icon('phone')}</button><button class="avatar" data-action="settings" aria-label="个人设置">${esc(state.profile.name.slice(0,1))}</button></div></div>`;
}
function render(){
  coverCleanup?.();coverCleanup=null;
  renderShell();
  const view={home:renderHome,train:renderTrain,history:renderHistory,learn:renderLearn,workout:renderWorkout}[state.route]||renderHome;
  $('#content').innerHTML=(state.readOnly?'<div class="offline-banner">另一个PingFit窗口正在记录训练。此窗口为只读；关闭其他窗口后重新打开，可继续编辑。</div>':'')+(state.offline?'<div class="offline-banner">当前离线 · 训练与照片仍可保存在本机，平台教程需要联网打开。</div>':'')+view();
  hydratePhotos();tick();const cover=$('.cover-carousel');if(cover){const stop=mountCoverCarousel(cover);const dayChanged=()=>{if(state.route==='home')render();};cover.addEventListener('coverdaychange',dayChanged);coverCleanup=()=>{stop();cover.removeEventListener('coverdaychange',dayChanged);};}
}
function weekCard(){const w=week();return `<div class="card week-card"><div class="week-heading"><h3>本周训练</h3><span>保持自己的节奏</span></div><div class="week-numbers"><span class="numeric">${w.sessions}</span><span class="goal">/ ${state.profile.weeklyGoal} 次目标</span></div><div class="week-progress"><span style="width:${Math.min(100,w.sessions/state.profile.weeklyGoal*100)}%"></span></div><p class="week-hint">${w.sessions>=state.profile.weeklyGoal?'这周的目标已达成，认真恢复也很重要。':w.sessions?'已经迈出一步，按自己的安排继续。':'每周 2–3 次，从一次完整的训练开始。'}</p><div class="week-days">${w.days.map(d=>`<div class="week-day ${d.count?'done':''} ${d.key===today()?'today':''}"><span>周${d.label}</span><b>${d.count?icon('check'):new Date(d.key+'T12:00:00').getDate()}</b></div>`).join('')}</div><button class="button soft full" data-action="route" data-route="history">查看训练日记 ${icon('arrow')}</button></div>`;}
function coverHTML(){const covers=getDailyCovers(),date=new Date();return `<section class="hero cover-carousel" role="region" aria-roledescription="轮播图" aria-label="每日运动封面" data-active-index="0"><div class="cover-stage">${covers.map((c,i)=>`<div class="cover-slide ${i===0?'is-active':''}" data-cover-index="${i}" role="group" aria-roledescription="幻灯片" aria-label="${i+1} / ${covers.length}" aria-hidden="${i!==0}"><img src="${c.image}" alt="" ${i===0?'fetchpriority="high"':'loading="eager"'}><div class="cover-copy"><div class="eyebrow">${esc(c.eyebrow)}</div><h2>${c.titleLines.map(esc).join('<br>')}</h2><p>${c.subtitleLines.map(esc).join('<br>')}</p></div></div>`).join('')}</div><div class="cover-day-tag">${date.getMonth()+1}.${String(date.getDate()).padStart(2,'0')} · 今日封面</div><button class="button lime cover-cta" data-action="${state.active?'resume':'choose-training'}">${icon('play')}${state.active?'继续我的训练':'开始今天的训练'} ${icon('arrow')}</button><div class="cover-controls"><button class="cover-prev" aria-label="上一张封面">${icon('left')}</button><div class="cover-dots">${covers.map((c,i)=>`<button class="cover-dot ${i===0?'is-active':''}" data-cover-to="${i}" aria-label="查看第 ${i+1} 张封面" aria-current="${i===0}"></button>`).join('')}</div><button class="cover-next" aria-label="下一张封面">${icon('right')}</button><button class="cover-pause" data-pause-label="暂停" data-play-label="播放" aria-label="暂停或继续轮播">暂停</button></div><span class="cover-status" aria-live="polite">第 1 / 3 张</span></section>`;}
function renderHome(){
  const w=week(),recent=completed().slice(0,3),weekKcal=state.profile.weightConfirmed?num(Math.round(w.kcal)):'—';
  return `${state.active?`<div class="resume-banner"><div><strong>你有一场未完成的训练</strong><p>${esc(titleFor(state.active))} · ${state.active.exercises.length} 个动作，进度已自动保存</p></div><button class="button small lime" data-action="route" data-route="workout">继续训练 ${icon('arrow')}</button></div>`:''}<div class="home-grid"><div class="home-main">${coverHTML()}<div class="mini-stats"><div class="mini-stat"><span>${icon('clock')}本周运动</span><strong>${num(Math.round(w.minutes))}</strong><small>分钟</small></div><div class="mini-stat"><span>${icon('flame')}本周热量估算</span><strong>${weekKcal}</strong><small>kcal</small></div><div class="mini-stat"><span>${icon('dumbbell')}本周训练量</span><strong>${num(Math.round(w.volume))}</strong><small>kg</small></div></div><div class="section-title"><div><h2>今天想练哪里？</h2><p>从身体部位出发，找到适合的动作。</p></div><button class="text-link" data-action="route" data-route="train">全部动作 ${icon('right')}</button></div><div class="body-parts">${PARTS.filter(p=>p.id!=='all').map(p=>`<button class="part-card" data-action="part" data-id="${p.id}"><span class="part-visual">${icon(p.id)}</span><strong>${p.label}</strong><small>${EXERCISES.filter(e=>e.part===p.id).length} 个动作</small></button>`).join('')}</div><div class="section-title"><div><h2>按自己的节奏开练</h2><p>从模板开始，动作和重量随时调整。</p></div></div><div class="plans">${PLANS.map((p,i)=>`<button class="plan-card" data-action="plan" data-id="${p.id}"><span class="plan-code">${['BUILD YOUR BASE','LOWER BODY','UPPER BODY'][i]}</span><span class="plan-decoration">${icon(['dumbbell','legs','back'][i])}</span><h3>${esc(p.name)}</h3><p>${esc(p.tag)} · ${p.exerciseIds.length} 个动作</p><div class="plan-foot"><span>${icon('clock')}参考 ${p.minutes} 分钟</span><span class="plan-arrow">${icon('arrow')}</span></div></button>`).join('')}</div><div class="section-title"><h2>最近的训练</h2><a class="text-link" href="#history">全部记录 ${icon('right')}</a></div><div class="card" style="padding-top:5px;padding-bottom:5px">${recent.length?recent.map(s=>`<button class="recent-row" style="width:100%;text-align:left" data-action="record" data-id="${s.id}"><span class="session-symbol">${icon(s.cardio?.length&&!s.exercises?.length?'activity':'dumbbell')}</span><span class="session-detail"><h4>${esc(titleFor(s))}</h4><p>${esc(dateLabel(s.startedAt))} · ${summary(s).completedSets} 组已完成</p></span><span><strong class="numeric">${num(Math.round(summary(s).durationMinutes))}</strong><small> min</small></span></button>`).join(''):`<div class="empty-compact"><span class="empty-icon">${icon('book')}</span><div><h4>从第一组开始，写下你的进步</h4><p>完成训练后，总结会出现在这里。</p></div></div>`}</div></div><aside class="home-aside">${weekCard()}<div class="side-tip"><div class="eyebrow">A LITTLE REMINDER</div><h3>进步的参照，<br>是上一次的自己。</h3><p>记录重量、次数和身体感受。<br>不用每天训练，也能看见积累。</p><div class="tip-line"></div></div>${!state.profile.weightConfirmed?`<div class="side-tip"><div class="flex">${icon('flame')}<h3 style="margin:0;font-size:12px">完善热量估算</h3></div><p style="margin-top:10px">设置体重后，查看力量与有氧的热量估算。</p><button class="text-link" style="margin-top:13px" data-action="settings">设置我的体重 ${icon('right')}</button></div>`:''}</aside></div>`;
}
function renderTrain(){
  const q=state.search.trim().toLowerCase(),items=EXERCISES.filter(e=>(state.part==='all'||e.part===state.part)&&(!q||[e.name,e.equipment,PARTS.find(p=>p.id===e.part)?.label].join(' ').toLowerCase().includes(q)));
  return `<div class="page-heading"><div><h1>把动作练明白</h1><p>按部位找动作，了解器械和要点，再加入你的训练。</p></div><button class="button soft small" data-action="recognize">${icon('scan')}拍照辅助录入</button></div><div class="search-field">${icon('search')}<input id="exercise-search" type="search" value="${esc(state.search)}" placeholder="搜索动作或器械，例如：高位下拉" aria-label="搜索动作或器械"></div><div class="filters">${PARTS.map(p=>`<button class="chip ${state.part===p.id?'active':''}" data-action="filter-part" data-id="${p.id}">${p.label}</button>`).join('')}</div><div class="exercise-grid">${items.map(e=>`<article class="exercise-card ${state.selected.has(e.id)?'selected':''}"><button class="select-toggle" data-action="select-exercise" data-id="${e.id}" aria-label="${state.selected.has(e.id)?'取消选择':'选择'}${esc(e.name)}" aria-pressed="${state.selected.has(e.id)}">${state.selected.has(e.id)?icon('check'):icon('plus')}</button><button class="exercise-visual ${e.part}" data-action="exercise" data-id="${e.id}" aria-label="查看${esc(e.name)}动作指导"><span class="big-type">${({legs:'LEG',back:'BACK',shoulders:'SHLDR',chest:'CHEST',arms:'ARM',core:'CORE'})[e.part]}</span>${icon(e.part)}</button><div class="exercise-content"><button data-action="exercise" data-id="${e.id}"><h3>${esc(e.name)}</h3><p>${esc(e.equipment)}</p><div class="exercise-card-bottom"><span>${PARTS.find(p=>p.id===e.part)?.label} · ${esc(e.difficulty)}</span>${icon('arrow')}</div></button></div></article>`).join('')}</div>${!items.length?`<div class="empty-state"><span class="empty-icon">${icon('search')}</span><h3>还没找到这个动作</h3><p>试试器械名称，或切换身体部位。</p><button class="button soft" data-action="clear-search">显示全部动作</button></div>`:''}${state.selected.size?`<div class="selected-bar"><div><span>已选择 ${state.selected.size} 个动作</span><small>${state.active?'加入当前训练，继续你的节奏':'组数和重量可以在训练中调整'}</small></div><div class="flex"><button class="text-link" style="color:#c7d5bb" data-action="clear-selection">清空</button><button class="button lime small" data-action="start-selected">${state.active?'加入训练':'开始训练'} ${icon('arrow')}</button></div></div>`:''}`;
}
function showExercise(id){const e=getExercise(id);if(!e)return;modal(e.name,`<div class="detail-heading"><span class="detail-visual">${icon(e.part)}</span><div><h3>${esc(e.equipment)}</h3><p>${esc(PARTS.find(p=>p.id===e.part)?.label)} · ${esc(e.difficulty)} · ${e.unit==='seconds'?'按秒记录':'按组与次数记录'}</p></div></div><div class="detail-section"><h3>动作怎么做</h3><ol class="steps">${e.steps.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div><div class="detail-section"><h3>留意这些细节</h3><div class="tips">${e.tips.map(t=>`<p>${esc(t)}</p>`).join('')}</div></div><div class="detail-section"><h3>可参考的其他动作</h3><div class="detail-tags">${e.alternatives.map(a=>getExercise(a)).filter(Boolean).map(a=>`<button class="chip" data-action="exercise" data-id="${a.id}">${esc(a.name)}</button>`).join('')}</div></div><div class="detail-actions"><button class="button soft" data-action="learn-exercise" data-id="${id}">${icon('play')}找教学视频</button><button class="button lime" data-action="add-one" data-id="${id}">${icon('plus')}${state.active?'加入训练':'加入待练'}</button></div><a class="source-link" href="${esc(e.sourceUrl)}" target="_blank" rel="noopener noreferrer">动作参考：ACE Exercise Library ↗</a><p class="inline-note">模板与默认组数可自行调整。初次使用器械，请先核对机器说明和动作；出现疼痛时停止本次动作。</p>`,'exercise');}
function showPlan(id){const p=PLANS.find(p=>p.id===id);if(!p)return;modal(p.name,`<p class="modal-subtitle">${esc(p.description)}</p><div class="pill">${icon('clock')}参考 ${p.minutes} 分钟 · ${p.exerciseIds.length} 个动作</div><div class="modal-list" style="margin-top:17px">${p.exerciseIds.map((id,i)=>{const e=getExercise(id);return `<button class="modal-exercise" data-action="exercise" data-id="${id}"><span class="exercise-number">${i+1}</span><span><h4>${esc(e.name)}</h4><p>${esc(e.equipment)}</p></span><span class="check">${icon('right')}</span></button>`;}).join('')}</div><div class="modal-footer"><button class="button lime full" data-action="start-plan" data-id="${p.id}">${state.active?'加入当前训练':'使用模板开始'} ${icon('arrow')}</button></div><p class="inline-note">训练时可以增删动作与组数。所示时长仅帮助安排时间，不是必须完成的目标。</p>`,'plan');}

async function refreshData(){state.sessions=await db.getSessions();state.favorites=await db.getFavorites();state.active=state.sessions.find(s=>s.status==='active')||null;}
function queueSave(s){if(storageBusy||state.readOnly)return Promise.reject(new Error('当前窗口暂时无法写入，请稍后重试。'));const snapshot=structuredClone(s),generation=dataGeneration;saveQueue=saveQueue.catch(()=>{}).then(async()=>{if(generation!==dataGeneration)return;await db.saveSession(snapshot);if(generation!==dataGeneration)return;const index=state.sessions.findIndex(x=>x.id===snapshot.id);if(index>=0)state.sessions[index]=snapshot;else state.sessions.unshift(snapshot);state.saveError=false;const label=$('#save-status');if(label)label.textContent='已自动保存';}).catch(error=>{state.saveError=true;const label=$('#save-status');if(label)label.textContent='保存失败，点此重试';toast('保存未完成：'+error.message);throw error;});return saveQueue;}
function scheduleSave(){if(storageBusy||state.readOnly||finishing)return;clearTimeout(saveTimer);const generation=dataGeneration;const label=$('#save-status');if(label)label.textContent='正在保存…';saveTimer=setTimeout(()=>{if(state.active&&generation===dataGeneration)queueSave(state.active).catch(()=>{});},350);}
async function saveNow(){if(storageBusy||state.readOnly||finishing)return;clearTimeout(saveTimer);if(state.active)await queueSave(state.active);else await saveQueue.catch(()=>{});}
async function startTraining(ids=[],title=''){
  if(storageBusy||state.readOnly)throw new Error('请在正在使用的PingFit窗口中编辑训练。');
  if(state.active){const newIds=ids.filter(id=>!state.active.exercises.some(e=>e.exerciseId===id));if(newIds.length){state.active.exercises.push(...createSession(newIds,state.profile).exercises);await saveNow();toast(`已加入 ${newIds.length} 个动作`);}else if(ids.length)toast('这些动作已在当前训练中');state.selected.clear();navigate('workout');return;}
  const s=createSession(ids,state.profile);s.title=title;s.runningSince=Date.now();s.restEndsAt=null;state.active=s;await saveNow();state.selected.clear();navigate('workout');
}
function renderWorkout(){
  const s=state.active;if(!s)return `<div class="empty-state"><span class="empty-icon">${icon('dumbbell')}</span><h3>现在开始，也刚刚好</h3><p>选几个想练的动作，或直接记录一次有氧。</p><div class="flex" style="justify-content:center"><button class="button lime" data-action="route" data-route="train">选择训练动作</button><button class="button soft" data-action="cardio-only">记录有氧</button></div></div>`;
  const sum=summary(s);return `<div class="workout-header"><div><div class="eyebrow">${s.runningSince?'TRAINING IN PROGRESS':'TRAINING PAUSED'}</div><div class="workout-timer" id="workout-clock">${timeString(elapsed(s))}</div><button class="saving-text" id="save-status" data-action="retry-save">${state.saveError?'保存失败，点此重试':'已自动保存'}</button></div><div class="workout-actions"><button class="icon-button" data-action="toggle-pause" aria-label="${s.runningSince?'暂停训练':'继续训练'}">${icon(s.runningSince?'pause':'play')}</button><button class="button lime small" data-action="finish">完成训练 ${icon('check')}</button></div></div><div class="workout-layout"><div><div class="section-title" style="margin-top:0"><h2>${esc(titleFor(s))}</h2><button class="text-link" data-action="edit-title">编辑名称</button></div>${s.exercises.map((e,i)=>`<section class="workout-exercise"><div class="exercise-title"><span class="exercise-number">${String(i+1).padStart(2,'0')}</span><div><button data-action="exercise" data-id="${e.exerciseId}" style="padding:0;text-align:left"><h3>${esc(e.name)}</h3><p>${esc(e.equipment)} · 查看动作要点 ↗</p></button></div><div class="exercise-tools"><button data-action="learn-exercise" data-id="${e.exerciseId}" aria-label="查找${esc(e.name)}教学">${icon('play')}</button><button data-action="remove-exercise" data-id="${e.id}" aria-label="删除${esc(e.name)}">${icon('close')}</button></div></div>${(()=>{const previous=completed().find(p=>p.exercises?.some(x=>x.exerciseId===e.exerciseId&&x.equipment===e.equipment&&x.sets.some(t=>t.done)));const sets=previous?.exercises.find(x=>x.exerciseId===e.exerciseId)?.sets.filter(t=>t.done)||[];return sets.length?`<p class="inline-note" style="margin:-8px 0 15px">上次 ${new Date(previous.startedAt).getMonth()+1}/${new Date(previous.startedAt).getDate()}：${sets.map(t=>`${num(t.weight)} kg × ${num(t.reps)} ${e.unit==='seconds'?'秒':'次'}`).join(' / ')}</p>`:'';})()}<div class="set-table"><span class="set-heading">组</span><span class="set-heading">重量 / KG</span><span class="set-heading">${e.unit==='seconds'?'时长 / 秒':'次数'}</span><span class="set-heading">完成</span><span></span>${e.sets.map((set,j)=>`<span class="set-index">${j+1}</span><input type="number" inputmode="decimal" min="0" max="2000" step="0.5" value="${esc(set.weight)}" data-set-input="weight" data-exercise="${e.id}" data-id="${set.id}" aria-label="${esc(e.name)}第${j+1}组重量"><input type="number" inputmode="numeric" min="1" max="${e.unit==='seconds'?3600:1000}" step="1" value="${esc(set.reps)}" data-set-input="reps" data-exercise="${e.id}" data-id="${set.id}" aria-label="${esc(e.name)}第${j+1}组${e.unit==='seconds'?'秒数':'次数'}"><button class="done-button ${set.done?'done':''}" data-action="set-done" data-exercise="${e.id}" data-id="${set.id}" aria-label="${esc(e.name)}第${j+1}组${set.done?'取消完成':'完成'}" aria-pressed="${set.done}">${icon('check')}</button><button class="remove-set" data-action="remove-set" data-exercise="${e.id}" data-id="${set.id}" aria-label="删除第${j+1}组">${icon('close')}</button>`).join('')}</div><button class="add-set" data-action="add-set" data-id="${e.id}">${icon('plus')}添加一组</button></section>`).join('')}<div class="workout-bottom-buttons"><button class="button outline" data-action="route" data-route="train">${icon('plus')}添加动作</button><button class="button outline" data-action="cardio">${icon('activity')}添加有氧</button><button class="button outline" data-action="recognize">${icon('scan')}拍照录入</button></div>${s.cardio.length?`<section class="card" style="margin-bottom:17px"><h3>有氧训练</h3>${s.cardio.map(c=>`<div class="cardio-row"><div><strong>${esc(CARDIO_TYPES.find(t=>t.id===(c.typeId||c.type))?.label||'有氧')}</strong><p>${num(c.minutes)} 分钟${c.distance?' · '+num(c.distance)+' km':''} · ${c.caloriesSource!=='estimate'?num(c.kcal)+' kcal 记录值':(state.profile.weightConfirmed?num(Math.round(summarizeCardio(c,state.profile,s).kcal))+' kcal 估算':'设置体重后估算')}</p></div><div class="flex"><button class="text-link" data-action="edit-cardio" data-id="${c.id}">编辑</button><button class="icon-button" data-action="remove-cardio" data-id="${c.id}" aria-label="删除有氧记录">${icon('close')}</button></div></div>`).join('')}</section>`:''}<section class="card"><div class="flex space"><h3>训练照片与感受</h3><button class="text-link" data-action="add-photos">${icon('plus')}添加照片</button></div><div class="photo-grid" data-photo-grid="${s.id}" data-editable="true"></div><p class="photo-caption">照片与本次训练一起保存，可以记录状态或器械信息。</p><textarea id="workout-notes" placeholder="今天练得怎么样？记下动作感受、器械编号或下次想调整的地方。" style="margin-top:18px;font-size:12px">${esc(s.notes)}</textarea><div class="feeling-picker" style="margin-top:13px">${['状态不错','稳步完成','有些吃力'].map(f=>`<button class="feeling-button ${s.feeling===f?'selected':''}" data-action="feeling" data-value="${f}">${f}</button>`).join('')}</div></section><button class="text-link" style="color:#ae9e8f;margin:22px 0" data-action="discard">放弃并删除这次草稿</button></div><aside class="summary-side"><div class="card"><h3>每一组，都算数</h3><div class="live-summary"><div><strong id="live-sets">${sum.completedSets}</strong><small>组</small><p>已完成</p></div><div><strong id="live-volume">${num(sum.totalVolume)}</strong><small>kg</small><p>累计训练量</p></div><div><strong id="live-kcal">${kcalValue(s)}</strong><small>kcal</small><p>${state.profile.weightConfirmed?'热量估算':'设备记录热量'}</p></div><div><strong id="live-exercises">${sum.exerciseCount}</strong><small>个</small><p>已练动作</p></div></div><p class="inline-note">${state.profile.weightConfirmed?'热量为含静息消耗的粗估；未暂停的组间休息计入时长。结束时请核对总时长。':'设置体重后显示热量估算。'}<br>训练量为已完成组的重量 × 次数。</p>${!state.profile.weightConfirmed?'<button class="text-link" style="margin-top:9px" data-action="settings">设置我的体重 →</button>':''}</div><div class="rest-card"><h4 id="rest-label">${s.restEndsAt?'组间休息':'下一组，准备好再开始'}</h4><div class="rest-time" id="rest-clock">${s.restEndsAt?timeString(Math.max(0,(s.restEndsAt-Date.now())/1000)):timeString(state.profile.restSeconds)}</div><button data-action="rest">${s.restEndsAt?'结束休息':'开始休息计时'}</button></div><div class="card"><div class="eyebrow" style="font-size:9px;color:#a8b59b">A STEADY PACE</div><h3 style="margin-top:12px;line-height:1.9">动作的质量，<br>比数字更重要。</h3><p class="inline-note">用可控制的重量完成动作。休息后再开始下一组，按身体感受调整。</p></div></aside></div>`;
}
function updateLive(){const s=state.active;if(!s)return;const v=summary(s);for(const [id,value]of Object.entries({'live-sets':v.completedSets,'live-volume':num(v.totalVolume),'live-kcal':kcalValue(s),'live-exercises':v.exerciseCount})){const el=$('#'+id);if(el)el.textContent=value;}}
function tick(){const s=state.active;if(!s)return;const clock=$('#workout-clock');if(clock)clock.textContent=timeString(elapsed(s));if(s.restEndsAt){const remain=Math.ceil((s.restEndsAt-Date.now())/1000),el=$('#rest-clock');if(el)el.textContent=timeString(remain);if(remain<=0&&!restNotified){restNotified=true;s.restEndsAt=null;scheduleSave();toast('休息结束，准备好再开始下一组');if($('#rest-label'))$('#rest-label').textContent='休息结束，准备好再开始';try{const ctx=new(window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),gain=ctx.createGain();o.connect(gain);gain.connect(ctx.destination);gain.gain.value=.06;o.frequency.value=660;o.start();o.stop(ctx.currentTime+.15);o.onended=()=>ctx.close();}catch{}}}if(clock)updateLive();}
setInterval(tick,1000);
setInterval(()=>{if(!storageBusy&&!state.readOnly&&!finishing&&state.active?.runningSince)saveNow().catch(()=>{});},15000);

function cardioForm(item={},fields=null,recognition=null){
  const c=fields?{...item,...fields}:item;cardioContext={id:item.id||uid(),photoId:uid(),recognition,sessionId:state.active?.id};
  modal(fields?'核对有氧数据':'记录有氧',`<p class="modal-subtitle">${fields?'以下数值来自图片文字识别，请逐项核对。':'可以记录设备上的热量，也可以根据体重和时长估算。'}</p><form id="cardio-form"><div class="form-grid"><label class="form-field wide">运动类型<select name="typeId">${CARDIO_TYPES.map(t=>`<option value="${t.id}" ${t.id===(c.typeId||c.type||'walk')?'selected':''}>${esc(t.label)} · ${esc(t.description)}</option>`).join('')}</select></label><label class="form-field">运动时长 / 分钟<input name="minutes" type="number" min="0.1" max="1440" step="0.1" required inputmode="decimal" value="${esc(c.minutes??'')}" placeholder="例如 20"></label><label class="form-field">距离 / km（选填）<input name="distance" type="number" min="0" max="1000" step="0.01" inputmode="decimal" value="${esc(c.distance??'')}" placeholder="例如 2.5"></label><label class="form-field">设备热量 / kcal（选填）<input name="kcal" type="number" min="0" max="20000" step="1" inputmode="numeric" value="${esc(c.caloriesSource==='estimate'?'':c.kcal??'')}" placeholder="留空则估算"></label><label class="form-field">强度<select name="intensity"><option value="moderate">一般 / 中等</option><option value="light" ${c.intensity==='light'?'selected':''}>轻松</option><option value="vigorous" ${c.intensity==='vigorous'?'selected':''}>较高</option></select></label></div><p class="inline-note">热量只采用一种来源。设备数值存在时使用记录值；留空时使用对应活动的 MET 估算。部分活动仅提供一般强度口径。</p><div class="form-actions"><button class="button soft" type="button" data-action="close-modal">取消</button><button class="button lime" type="submit">保存有氧记录</button></div></form>`,'cardio');
}
async function finishDialog(){await saveNow();const s=state.active;if(!s)return;const v=summary(s);if(!v.completedSets&&!s.cardio.length){toast('先完成一组动作，或添加一条有氧记录');return;}modal('把今天的认真，记下来',`<p class="modal-subtitle">${esc(titleFor(s))} · ${v.completedSets} 组力量训练${s.cardio.length?' · '+s.cardio.length+' 项有氧':''}</p><form id="finish-form"><div class="form-grid"><label class="form-field wide">训练名称<input name="title" maxlength="60" required value="${esc(titleFor(s))}"></label><label class="form-field">本次总运动时长 / 分钟<input name="minutes" type="number" min="0.1" max="1440" step="0.1" inputmode="decimal" required value="${Math.max(.1,Math.round(Math.max(v.durationMinutes,v.cardioMinutes)*10)/10)}"></label><label class="form-field">本次感受<select name="feeling"><option value="">选择你的感受</option>${['状态不错','稳步完成','有些吃力'].map(f=>`<option ${s.feeling===f?'selected':''}>${f}</option>`).join('')}</select></label><label class="form-field wide">训练笔记<textarea name="notes" maxlength="10000">${esc(s.notes)}</textarea></label></div><div class="notice green-note" style="margin-top:17px">总时长包含有氧，系统会扣除有氧时长后估算力量部分。补录过去的训练时，可以修改这里的总时长。</div><div class="form-actions"><button class="button soft" type="button" data-action="close-modal">再练一会儿</button><button class="button lime" type="submit">保存本次训练 ${icon('check')}</button></div></form>`,'finish');}

function renderHistory(){
  const all=completed(),w=week();let list=state.historyPeriod==='week'?all.filter(s=>w.days.some(d=>d.key===localDateKey(s.startedAt))):all;
  if(state.historyDay)list=all.filter(s=>localDateKey(s.startedAt)===state.historyDay);
  const vals=list.map(summary),stats={count:list.length,minutes:vals.reduce((n,v)=>n+v.durationMinutes,0),volume:vals.reduce((n,v)=>n+v.totalVolume,0),kcal:vals.reduce((n,v)=>n+v.totalKcal,0)};
  return `<div class="page-heading"><div><h1>每一次进步，都在这里</h1><p>回看训练、照片和感受，找到属于你的节奏。</p></div><button class="button soft small" data-action="settings">${icon('download')}备份数据</button></div><div class="filters"><button class="chip ${state.historyPeriod==='week'&&!state.historyDay?'active':''}" data-action="history-period" data-value="week">本周</button><button class="chip ${state.historyPeriod==='all'&&!state.historyDay?'active':''}" data-action="history-period" data-value="all">全部记录</button>${state.historyDay?`<button class="chip active" data-action="clear-history-day">${esc(state.historyDay)} ${icon('close')}</button>`:''}</div><div class="history-stats">${[['训练次数',stats.count,'次','calendar'],['累计运动',Math.round(stats.minutes),'分钟','clock'],['热量估算',state.profile.weightConfirmed?Math.round(stats.kcal):'—','kcal','flame'],['累计训练量',Math.round(stats.volume),'kg','dumbbell']].map(([l,n,u,i])=>`<div class="history-stat"><span class="stat-icon">${icon(i)}</span><p>${l}</p><strong>${typeof n==='number'?num(n):n}</strong><small>${u}</small></div>`).join('')}</div>${state.historyDay&&list.length?`<div class="notice green-note" style="margin-bottom:20px">每日总结：${esc(dateLabel(state.historyDay+'T12:00:00'))}完成 ${list.length} 次训练，累计 ${num(Math.round(stats.minutes))} 分钟、${vals.reduce((n,v)=>n+v.completedSets,0)} 组力量、${num(vals.reduce((n,v)=>n+v.cardioMinutes,0))} 分钟有氧。</div>`:''}<div class="history-layout"><div>${list.length?list.map(s=>{const d=new Date(s.startedAt),v=summary(s);return `<button class="history-item" data-action="record" data-id="${s.id}"><span class="history-date"><strong>${String(d.getDate()).padStart(2,'0')}</strong><small>${d.getMonth()+1} 月</small></span><span class="history-main"><h3>${esc(titleFor(s))}</h3><p>${v.completedSets} 组力量 · ${num(Math.round(v.durationMinutes))} 分钟${s.feeling?' · '+esc(s.feeling):''}</p>${s.photoIds?.length?`<span class="history-photo-indicator">${icon('photo')} ${s.photoIds.length} 张照片</span>`:''}</span><span class="history-number"><strong>${kcalValue(s)}</strong><small>kcal</small></span></button>`;}).join(''):`<div class="empty-state"><span class="empty-icon">${icon('calendar')}</span><h3>${state.historyDay?'这一天，留给恢复和生活':'你的训练日记，等你写下第一篇'}</h3><p>每周练几次，都值得好好记录。完成一次训练后，这里会留下你的总结与照片。</p><button class="button lime" data-action="choose-training">开始一次训练 ${icon('arrow')}</button></div>`}</div><aside class="history-aside">${calendarHTML()}<div class="card" style="margin-top:19px"><h3 style="font-size:13px">看见重量的变化</h3>${progressHTML(all)}</div></aside></div>`;
}
function calendarHTML(){const date=state.calendar,year=date.getFullYear(),month=date.getMonth(),days=new Date(year,month+1,0).getDate(),first=(new Date(year,month,1).getDay()+6)%7,counts=new Map();completed().forEach(s=>counts.set(localDateKey(s.startedAt),(counts.get(localDateKey(s.startedAt))||0)+1));return `<div class="calendar"><div class="calendar-heading"><h3>${year} 年 ${month+1} 月</h3><span class="month-controls"><button data-action="month" data-delta="-1" aria-label="上个月">${icon('left')}</button><button data-action="month" data-delta="1" aria-label="下个月">${icon('right')}</button></span></div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map(x=>`<span class="weekday">${x}</span>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>{const key=localDateKey(new Date(year,month,i+1));return `<button class="calendar-day ${counts.has(key)?'marked':''} ${key===today()?'today':''}" data-action="calendar-day" data-date="${key}" aria-label="${key}，${counts.get(key)||0}次训练">${i+1}</button>`;}).join('')}</div><p class="calendar-caption"><i></i>训练日 · 点击日期查看每日总结</p></div>`;}
function progressHTML(all){const ids=[...new Set(all.flatMap(s=>(s.exercises||[]).filter(e=>e.sets.some(t=>t.done)).map(e=>e.exerciseId)))];if(!ids.length)return '<p class="inline-note" style="padding:25px 0">记录几次训练后，在这里比较同一动作的重量或保持时长。</p>';if(!ids.includes(state.progressExercise))state.progressExercise=ids[0];const e=getExercise(state.progressExercise),points=all.slice().reverse().filter(s=>s.exercises.some(e=>e.exerciseId===state.progressExercise&&e.sets.some(t=>t.done))).slice(-6).map(s=>({date:new Date(s.startedAt),value:Math.max(...s.exercises.filter(e=>e.exerciseId===state.progressExercise).flatMap(e=>e.sets.filter(t=>t.done).map(t=>Number(e.unit==='seconds'?t.reps:t.weight)||0)))})),max=Math.max(1,...points.map(p=>p.value));return `<select id="progress-exercise" aria-label="选择查看进度的动作" style="font-size:11px;width:100%;margin-top:15px;padding:9px">${ids.map(id=>`<option value="${id}" ${id===state.progressExercise?'selected':''}>${esc(getExercise(id)?.name||id)}</option>`).join('')}</select><div class="chart-bars" aria-label="每次训练的最高${e?.unit==='seconds'?'保持秒数':'记录重量'}">${points.map(p=>`<div class="chart-column"><small>${num(p.value)}</small><div class="bar" style="height:${p.value/max*90+3}px"></div><span>${p.date.getMonth()+1}/${p.date.getDate()}</span></div>`).join('')}</div><p class="inline-note">每次训练的最高${e?.unit==='seconds'?'保持时长 / 秒':'记录重量 / kg'}。仅比较同一动作与同一器械。</p>`;}
async function showRecord(id){const s=state.sessions.find(x=>x.id===id);if(!s)return;currentRecordId=id;const v=summary(s),photoCount=s.photoIds?.length||0;modal('本次训练总结',`<div class="record-summary"><div class="eyebrow">${esc(dateLabel(s.startedAt))}</div><h2>${esc(titleFor(s))}</h2><div class="record-metrics"><div><strong>${num(Math.round(v.durationMinutes))}</strong><p>运动分钟</p></div><div><strong>${v.completedSets}</strong><p>已完成组数</p></div><div><strong>${kcalValue(s)}</strong><p>kcal ${!v.weightAssumed?'估算 / 记录':'设备记录'}</p></div></div><p class="record-summary-text">${v.exerciseCount?`今天练了 ${v.exerciseCount} 个动作，完成 ${v.completedSets} 组，累计训练量 ${num(v.totalVolume)} kg。`:''}${v.cardioMinutes?`有氧运动 ${num(v.cardioMinutes)} 分钟。`:''}${s.feeling?'本次感受：'+esc(s.feeling)+'。':''}</p></div>${s.exercises.filter(e=>e.sets.some(t=>t.done)).map(e=>`<div class="record-exercise"><strong>${esc(e.name)}</strong><p>${esc(e.equipment)} · ${e.sets.filter(t=>t.done).map(t=>`${num(t.weight)} kg × ${num(t.reps)} ${e.unit==='seconds'?'秒':'次'}`).join(' / ')}</p></div>`).join('')}${s.cardio.map(c=>`<div class="record-exercise"><strong>${esc(CARDIO_TYPES.find(t=>t.id===(c.typeId||c.type))?.label||'有氧')}</strong><p>${num(c.minutes)} 分钟${c.distance?' · '+num(c.distance)+' km':''} · ${c.caloriesSource==='estimate'?'按体重和强度估算':num(c.kcal)+' kcal 记录值'}</p></div>`).join('')}${s.notes?`<div class="record-notes">${esc(s.notes)}</div>`:''}<div class="section-title"><h3>训练照片 ${photoCount?`· ${photoCount}`:''}</h3><button class="text-link" data-action="add-record-photos" data-id="${s.id}">${icon('plus')}添加</button></div><div class="photo-grid" data-photo-grid="${s.id}" data-editable="true"></div><p class="inline-note">${!v.weightAssumed?`热量口径：力量估算 ${num(Math.round(v.strengthKcal))} kcal，有氧 ${num(Math.round(v.cardioKcal))} kcal；体重 ${v.weightKg} kg。MET 估算含静息消耗。`:'未设置体重时，仅展示已录入的设备热量；估算部分暂不显示。'}<br>照片和记录保存在本机，建议定期导出备份。</p><div class="form-actions"><button class="button danger small" data-action="delete-record" data-id="${s.id}">${icon('trash')}删除</button><button class="button soft small" data-action="edit-record" data-id="${s.id}">修改记录</button><button class="button lime small" data-action="repeat-record" data-id="${s.id}">再练一次 ${icon('arrow')}</button></div>`,'record');await hydratePhotos();}
function editRecord(id){const s=state.sessions.find(x=>x.id===id);if(!s)return;editingId=id;modal('修改训练记录',`<form id="edit-record-form"><div class="form-grid"><label class="form-field wide">训练名称<input name="title" maxlength="60" required value="${esc(titleFor(s))}"></label><label class="form-field">训练日期<input name="date" type="date" required max="${today()}" value="${localDateKey(s.startedAt)}"></label><label class="form-field">总运动时长 / 分钟<input name="minutes" type="number" min="0.1" max="1440" step="0.1" required value="${summary(s).durationMinutes}"></label><label class="form-field wide">训练笔记<textarea name="notes" maxlength="10000">${esc(s.notes)}</textarea></label></div><div class="detail-section"><h3>力量记录</h3><p class="inline-note">勾选已完成的组；重量与次数修改后，训练量会同步更新。</p></div>${s.exercises.map((e,i)=>`<div class="record-exercise"><strong>${esc(e.name)}</strong><div class="set-table" style="margin-top:12px"><span class="set-heading">组</span><span class="set-heading">KG</span><span class="set-heading">${e.unit==='seconds'?'秒':'次'}</span><span class="set-heading">完成</span><span></span>${e.sets.map((t,j)=>`<span class="set-index">${j+1}</span><input type="number" name="w_${i}_${j}" value="${t.weight}" min="0" max="2000" step="0.5" required aria-label="${esc(e.name)}第${j+1}组重量"><input type="number" name="r_${i}_${j}" value="${t.reps}" min="1" max="3600" required aria-label="${esc(e.name)}第${j+1}组次数或秒数"><input type="checkbox" name="d_${i}_${j}" ${t.done?'checked':''} aria-label="${esc(e.name)}第${j+1}组已完成" style="width:20px;height:20px;justify-self:center"><span></span>`).join('')}</div></div>`).join('')}${s.cardio.length?'<div class="detail-section"><h3>有氧记录</h3></div>':''}${s.cardio.map((c,i)=>`<div class="record-exercise"><div class="form-grid"><label class="form-field wide">运动类型<select name="ct_${i}">${CARDIO_TYPES.map(t=>`<option value="${t.id}" ${t.id===(c.typeId||c.type)?'selected':''}>${esc(t.label)}</option>`).join('')}</select></label><label class="form-field">有氧分钟<input type="number" name="cm_${i}" value="${esc(c.minutes)}" min="0.1" max="1440" step="0.1" required></label><label class="form-field">距离 / km<input type="number" name="cd_${i}" value="${esc(c.distance??'')}" min="0" max="1000" step="0.01"></label><label class="form-field wide">设备或手填热量 / kcal（留空则估算）<input type="number" name="ck_${i}" value="${esc(c.caloriesSource==='estimate'?'':c.kcal??'')}" min="0" max="20000" step="1"></label></div></div>`).join('')}<div class="form-actions"><button class="button soft" type="button" data-action="record" data-id="${id}">取消</button><button class="button lime" type="submit">保存修改</button></div></form>`,'edit-record');}

function renderLearn(){const keywords=['高位下拉 动作教学','练腿 器械使用','推肩 新手教学','跑步机 使用方法'];return `<div class="page-heading"><div><h1>好动作，值得反复学</h1><p>把找到的教学留在这里，下次训练直接打开。</p></div><button class="button soft small" data-action="add-favorite">${icon('plus')}收藏教程</button></div><div class="learn-layout"><div><section class="learn-search"><div class="eyebrow">LEARN. PRACTICE. REPEAT.</div><h2>今天，想把哪个动作练好？</h2><p>输入动作、器械或博主名称，前往抖音 / 小红书搜索。</p><form id="learn-search-form"><input id="tutorial-query" name="query" type="search" placeholder="例如：高位下拉 标准动作" value="${esc(state.tutorialQuery||'')}" required aria-label="教学视频搜索词"><button class="button" type="submit">搜教程 ${icon('search')}</button></form><div class="platform-buttons"><button class="platform-button" data-action="platform-search" data-platform="douyin"><span class="platform-mark">♪</span>去抖音搜索 ${icon('arrow')}</button><button class="platform-button" data-action="platform-search" data-platform="xhs"><span class="platform-mark red">小红书</span>去小红书搜索 ${icon('arrow')}</button><button class="platform-button" data-action="copy-query">${icon('copy')}复制搜索词</button></div><div class="keyword-list">${keywords.map(q=>`<button data-action="keyword" data-query="${esc(q)}">${esc(q)}</button>`).join('')}</div></section><div class="section-title"><h2>我的教学收藏</h2><span class="muted" style="font-size:10px">${state.favorites.length} 个教程</span></div>${state.favorites.length?state.favorites.map(f=>`<article class="favorite-card"><div class="flex"><span class="platform-mark ${f.platform==='xhs'?'red':''}">${f.platform==='xhs'?'小红书':f.platform==='douyin'?'♪':'↗'}</span><h3>${esc(f.title)}</h3></div><p>${f.exerciseId?esc(getExercise(f.exerciseId)?.name||'已关联动作')+' · ':''}${esc(new URL(f.url).hostname)} · ${dateLabel(f.createdAt)}</p><div class="favorite-actions"><a class="text-link" href="${esc(f.url)}" target="_blank" rel="noopener noreferrer">打开原视频 ${icon('arrow')}</a><button data-action="delete-favorite" data-id="${f.id}" aria-label="删除收藏${esc(f.title)}">${icon('trash')}</button></div></article>`).join(''):`<div class="empty-state"><span class="empty-icon">${icon('book')}</span><h3>你的专属教学库</h3><p>在抖音或小红书复制喜欢的教程链接，保存并关联动作，练之前随时复看。</p><button class="button soft" data-action="add-favorite">${icon('link')}添加第一条教程</button></div>`}</div><aside class="learn-aside"><div class="card"><h3>找到，再好好练</h3><ol class="guide-list"><li>用具体动作与器械名搜索，也可以加上你信任的博主名称。</li><li>在原平台查看完整教学，比较动作步骤和注意事项。</li><li>复制视频的分享链接，回到PingFit收藏，关联到对应动作。</li></ol><p class="inline-note" style="margin-top:23px">平台搜索与播放需要联网，可能需要在原平台登录。无法跳转时，可以复制搜索词。</p></div></aside></div>`;}
function queryValue(){return ($('#tutorial-query')?.value||state.tutorialQuery||'').trim();}
function searchPlatform(platform,q=queryValue()){if(!q){toast('先输入动作、器械或博主名称');$('#tutorial-query')?.focus();return;}state.tutorialQuery=q;const url=platform==='xhs'?`https://www.xiaohongshu.com/search_result?keyword=${encodeURIComponent(q)}&source=web_search_result_notes`:`https://www.douyin.com/search/${encodeURIComponent(q)}`;window.open(url,'_blank','noopener,noreferrer');}
function favoriteForm(exerciseId=''){modal('收藏一个教学',`<p class="modal-subtitle">粘贴抖音、小红书或其他教学视频的分享链接，下次训练直接复看。</p><form id="favorite-form"><div class="form-grid"><label class="form-field wide">教程标题<input name="title" maxlength="150" required placeholder="例如：高位下拉的三个动作要点"></label><label class="form-field wide">链接或分享文案<textarea name="url" required maxlength="5000" placeholder="粘贴视频链接，也支持包含链接的分享文案"></textarea></label><label class="form-field wide">关联动作（选填）<select name="exerciseId"><option value="">暂不关联</option>${EXERCISES.map(e=>`<option value="${e.id}" ${e.id===exerciseId?'selected':''}>${esc(e.name)}</option>`).join('')}</select></label></div><div class="form-actions"><button class="button soft" type="button" data-action="close-modal">取消</button><button class="button lime" type="submit">保存收藏</button></div></form>`,'favorite');}

function settings(){const p=state.profile;modal('我的训练空间',`<form id="settings-form"><div class="form-grid"><label class="form-field wide">怎么称呼你<input name="name" maxlength="20" value="${esc(p.name)}" required></label><label class="form-field">体重 / kg<input name="weight" type="number" min="20" max="350" step="0.1" required inputmode="decimal" value="${esc(p.weight)}" aria-describedby="weight-note"><small id="weight-note">用于热量估算；首次请核对默认数值。</small></label><label class="form-field">每周训练目标<select name="weeklyGoal">${[2,3,4,5,6,7,1].map(n=>`<option value="${n}" ${Number(p.weeklyGoal)===n?'selected':''}>每周 ${n} 次</option>`).join('')}</select></label><label class="form-field wide">默认组间休息<select name="restSeconds">${[30,60,90,120,180].map(n=>`<option value="${n}" ${Number(p.restSeconds)===n?'selected':''}>${n} 秒</option>`).join('')}</select></label></div><div class="form-actions"><button class="button lime full" type="submit">保存个人设置</button></div></form><div class="settings-row" style="margin-top:20px"><div><h4>数据与照片保存在这台设备</h4><p id="storage-status">正在查看本地存储…</p></div>${icon('shield')}</div><div class="backup-tools"><button class="button outline small" data-action="export-backup">${icon('download')}导出完整备份</button><button class="button outline small" data-action="import-backup">${icon('upload')}恢复备份</button><button class="button outline small" data-action="install">${icon('phone')}主屏幕安装</button></div><p class="settings-note">备份包含训练、照片、个人设置和教程收藏。Safari 与主屏幕 App 的数据空间可能不同，请在日常使用的入口中备份。清理浏览器数据或更换设备后，需要用备份恢复。</p><div class="settings-row"><div><h4>图片辅助录入</h4><p>本地识别英文与数字；器械候选来自铭牌文字。</p></div><button class="text-link" data-action="recognize">试试 ${icon('right')}</button></div><div class="settings-row"><div><h4>动作与热量资料</h4><p>ACE Exercise Library · 2024 Compendium</p></div><a href="./SOURCES.md" class="text-link" target="_blank" rel="noopener">查看 ${icon('right')}</a></div><button class="text-link" style="color:#ba8572;margin-top:20px;font-size:10px" data-action="clear-data">清除这台设备的所有PingFit数据</button>`,'settings');db.storageUsage?.().then(u=>{const el=$('#storage-status');if(el)el.textContent=u?.usage?`当前站点约使用 ${num(u.usage/1024/1024)} MB`:'训练记录与照片通过本地数据库保存';}).catch(()=>{});}
function install(){modal('把PingFit放到主屏幕',`<div class="notice green-note">在 iPhone 的 Safari 中打开本站，再按下面的步骤操作。</div><div class="install-steps"><div class="install-step"><b>1</b><div><strong>点击 Safari 的“分享”</strong><p>通常是带向上箭头的方框图标。${icon('upload')}</p></div></div><div class="install-step"><b>2</b><div><strong>选择“添加到主屏幕”</strong><p>若显示“作为网页 App 打开”，请开启。</p></div></div><div class="install-step"><b>3</b><div><strong>点击“添加”，从图标进入</strong><p>首次打开保持联网，等待离线资源准备完成。</p></div></div></div><p class="inline-note">训练、照片和文字识别可在资源准备后离线使用；教学平台需要联网。本机数据请定期备份，建议固定从主屏幕图标使用。</p><button class="button lime full" data-action="close-modal" style="margin-top:22px">知道了</button>`,'install');}

async function hydratePhotos(){for(const grid of document.querySelectorAll('[data-photo-grid]')){const id=grid.dataset.photoGrid;try{const photos=await db.getPhotos(id);if(!grid.isConnected)continue;grid.innerHTML=photos.map(p=>{const key=p.id+':thumb';if(!state.photoUrls.has(key))state.photoUrls.set(key,URL.createObjectURL(p.thumbnail||p.blob));return `<div class="photo-item"><button data-action="view-photo" data-id="${p.id}" aria-label="查看${esc(p.name)}"><img src="${state.photoUrls.get(key)}" alt="${esc(p.name)}" loading="lazy"></button>${grid.dataset.editable?`<button class="photo-remove" data-action="remove-photo" data-id="${p.id}" data-session="${id}" aria-label="删除照片">${icon('close')}</button>`:''}<span class="photo-kind">${p.kind==='screen'?'设备记录':'训练照片'}</span></div>`;}).join('')+(grid.dataset.editable?`<button class="photo-add" data-action="add-record-photos" data-id="${id}" aria-label="添加训练照片">${icon('plus')}</button>`:'');}catch(e){grid.textContent='照片读取未完成，请重新打开。';}}}
async function attachPhotos(files,sessionId){if(!files.length)return;if(fileBusy||storageBusy)throw new Error('照片正在保存，请稍候。');const owner=state.sessions.find(s=>s.id===sessionId)||state.active;if(!owner){toast('先开始一次训练，再添加照片');return;}if((owner.photoIds?.length||0)+files.length>30){toast('每次训练最多保存 30 张照片');return;}const button=document.querySelector('[data-action="add-photos"]');if(button)button.disabled=true;fileBusy=true;let count=0;try{await saveNow();for(const file of files){const p=await preparePhoto(file);await db.savePhoto({...p,id:uid(),sessionId,createdAt:new Date().toISOString(),kind:'album'});count++;}await refreshData();if(state.modalKind==='record')await showRecord(sessionId);else{render();}toast(`已保存 ${count} 张照片`);}catch(e){await refreshData();render();toast(`已保存 ${count} 张，其他图片未完成：${e.message}`);}finally{fileBusy=false;if(button)button.disabled=false;}}
function recognitionIntro(){modal('照片辅助录入',`<p class="modal-subtitle">拍摄跑步机、单车等设备的结果屏幕，或有英文名称的器械铭牌。</p><div class="notice green-note">图片在设备本地识别，不上传。当前支持英文与数字，会提取时长、距离、热量等字段；结果需要你确认。</div><div class="install-steps"><div class="install-step"><b>1</b><div><strong>尽量正对屏幕拍摄</strong><p>让 TIME、DISTANCE、CALORIES 等标签清晰完整。</p></div></div><div class="install-step"><b>2</b><div><strong>识别后核对，再加入训练</strong><p>器械候选来自铭牌文字，无法仅凭外形判断型号。没有读到时可手动选择。</p></div></div></div><button class="button lime full" data-action="pick-recognition">${icon('scan')}选择或拍摄图片</button><p class="inline-note">首次使用需联网下载约 11 MB 识别资源；之后可离线使用。</p>`,'recognition-intro');}
async function recognizeFile(file){const job=++recognitionJob;state.recognition=null;let prepared,url;try{prepared=await preparePhoto(file);if(job!==recognitionJob)return;releaseURL('recognition');url=URL.createObjectURL(prepared.blob);state.photoUrls.set('recognition',url);modal('正在读取图片',`<img class="recognition-preview" src="${url}" alt="待识别的设备照片"><div class="recognition-progress"><span class="spinner"></span><span id="ocr-status">正在准备本地识别…</span></div><p class="inline-note">照片留在你的设备中。识别期间可以等待，也可以关闭后手动录入。</p>`,'recognition-running');const result=await recognizeWorkoutImage(prepared.blob,{onProgress:data=>{if(job!==recognitionJob||state.modalKind!=='recognition-running')return;const el=$('#ocr-status');if(el)el.textContent=data.progress?`本地文字识别 ${Math.round(data.progress*100)}%`:'正在加载识别资源…';}});if(job!==recognitionJob)return;state.recognition={...result,prepared,previewUrl:url,job};if(state.modalKind!=='recognition-running'){toast('图片识别完成，点拍照录入可查看结果');return;}showRecognition();}catch(e){if(job!==recognitionJob)return;if(state.modalKind!=='recognition-running'){toast('图片识别未完成，可以稍后重新拍摄或手动录入');return;}modal('这张图片暂时没读清',`<div class="notice">${esc(e.message)}</div><p class="inline-note">可以重新选择正对屏幕、文字清晰的照片，也可以手动记录。本次未填入任何推测数值。</p><div class="form-actions"><button class="button soft" data-action="cardio">手动记录</button><button class="button lime" data-action="pick-recognition">换一张图片</button></div>`,'recognition-error');}}
function showRecognition(){const r=state.recognition;if(!r)return recognitionIntro();modal('识别完成，请核对',`<img class="recognition-preview" src="${r.previewUrl}" alt="设备屏幕照片"><p class="modal-subtitle">${esc(r.method)}${Number.isFinite(r.confidence)?' · 文字置信度 '+r.confidence+'%':''}</p><div class="notice green-note">${esc(r.note)}${r.equipmentName?'<br>器械候选：'+esc(r.equipmentName):''}</div><div class="record-metrics" style="margin:20px 0">${[['minutes','时长 / 分钟'],['distance','距离 / km'],['kcal','设备 / kcal']].map(([key,label])=>`<div><strong style="font-size:28px">${r.fields[key]!==undefined?num(r.fields[key]):'—'}</strong><p>${label}</p></div>`).join('')}</div>${r.fields.weight!==undefined||r.fields.reps!==undefined||r.suggestedExerciseIds.length?`<button class="button soft full" data-action="apply-strength-recognition" style="margin-bottom:18px">核对重量 / 次数并记录一组</button>`:''}<details><summary class="text-link">查看读到的文字</summary><pre class="ocr-text">${esc(r.text)}</pre></details><div class="form-actions"><button class="button soft" data-action="pick-recognition">重新拍摄</button><button class="button lime" data-action="apply-recognition">核对并添加有氧</button></div>${r.suggestedExerciseIds.length?`<div class="detail-section"><h3>铭牌文字对应的动作</h3><div class="detail-tags">${r.suggestedExerciseIds.filter(id=>getExercise(id)).map(id=>`<button class="chip" data-action="exercise" data-id="${id}">${esc(getExercise(id).name)}</button>`).join('')}</div></div>`:''}`,'recognition-result');}

function strengthRecognition(){const r=state.recognition;if(!r)return;strengthContext={id:uid(),photoId:uid(),recognition:r};const first=r.suggestedExerciseIds[0]||'';modal('核对力量记录',`<p class="modal-subtitle">根据铭牌或屏幕文字辅助录入。请选择实际使用的动作与器械，并核对数字。</p><form id="recognition-strength-form"><div class="form-grid"><label class="form-field wide">训练动作<select name="exerciseId">${EXERCISES.map(e=>`<option value="${e.id}" ${e.id===first?'selected':''}>${esc(e.name)} · ${esc(e.equipment)}</option>`).join('')}</select></label><label class="form-field">本组重量 / kg<input name="weight" type="number" min="0" max="2000" step="0.5" value="${esc(r.fields.weight??0)}" required></label><label class="form-field">本组次数 / 保持秒数<input name="reps" type="number" min="1" max="3600" value="${esc(r.fields.reps??10)}" required></label></div><p class="inline-note">只保存你确认已完成的一组。平板支撑填写秒数，其他动作填写次数；自重的外加重量填 0 kg。</p><div class="form-actions"><button class="button soft" type="button" data-action="recognize">返回结果</button><button class="button lime" type="submit">保存已完成组</button></div></form>`,'recognition-strength');}

async function exportData(){await saveNow();toast('正在整理训练与照片备份…');const data=await db.exportBackup(),blob=new Blob([JSON.stringify(data)],{type:'application/json'}),url=URL.createObjectURL(blob),name=`PingFit备份-${today()}.json`;releaseURL('backup');state.photoUrls.set('backup',url);state.exportFile=new File([blob],name,{type:'application/json'});modal('备份已准备好',`<p class="modal-subtitle">包含 ${data.sessions.length} 次训练、${data.photos.length} 张照片、${data.favorites.length} 条教学收藏。</p><div class="notice green-note">请把文件保存到“文件”或自己的备份位置。备份包含你的照片与个人记录。</div><div class="form-actions"><a class="button lime" href="${url}" download="${name}">${icon('download')}下载备份</a>${navigator.canShare?.({files:[state.exportFile]})?'<button class="button soft" data-action="share-backup">保存到文件 / 分享</button>':''}</div>`,'backup-ready');}
async function importData(file){if(file.size>230*1024*1024)throw new Error('备份文件超过 230 MB，无法在此导入。');const data=validateAppBackup(JSON.parse(await file.text()));if(data.format!=='fitlog-backup'||data.version!==1||!Array.isArray(data.sessions)||!Array.isArray(data.photos))throw new Error('这不是支持的PingFit备份文件。');state.pendingBackup=data;modal('恢复这份备份？',`<p class="modal-subtitle">文件中有 ${data.sessions.length} 次训练、${data.photos.length} 张照片。</p><div class="notice">恢复会替换当前设备上的PingFit数据。建议先导出当前备份；取消不会修改任何记录。</div><div class="form-actions"><button class="button soft" data-action="close-modal">取消</button><button class="button lime" data-action="confirm-import">确认恢复</button></div>`,'import');}

async function handleAction(action,el){
  const id=el.dataset.id,s=state.active;
  if(storageBusy||finishing)return toast('数据正在处理中，请稍候。');
  const readActions=new Set(['close-modal','route','settings','install','resume','part','filter-part','clear-search','exercise','plan','history-period','calendar-day','clear-history-day','month','record','learn-exercise','platform-search','keyword','copy-query','view-photo']);
  if(state.readOnly&&!readActions.has(action))return toast('当前窗口为只读，请在正在使用的PingFit窗口中编辑。');
  if(action==='close-modal')return closeModal();
  if(action==='route')return navigate(el.dataset.route);
  if(action==='settings')return settings();
  if(action==='install')return install();
  if(action==='resume')return navigate('workout');
  if(action==='choose-training'){if(s)return navigate('workout');return modal('今天，按自己的节奏练',`<p class="modal-subtitle">选一个模板开始，或自由挑选动作。训练过程中都可以调整。</p><div class="stack">${PLANS.map(p=>`<button class="modal-exercise" data-action="plan" data-id="${p.id}"><span class="exercise-number">${icon('dumbbell')}</span><span><h4>${esc(p.name)}</h4><p>${p.exerciseIds.length} 个动作 · 参考 ${p.minutes} 分钟</p></span><span class="check">${icon('right')}</span></button>`).join('')}</div><div class="form-actions"><button class="button soft" data-action="cardio-only">只记录有氧</button><button class="button lime" data-action="route" data-route="train">自由选择动作 ${icon('arrow')}</button></div>`,'choose');}
  if(action==='part'){state.part=id;state.search='';return navigate('train');}
  if(action==='filter-part'){state.part=id;return render();}
  if(action==='clear-search'){state.part='all';state.search='';return render();}
  if(action==='exercise')return showExercise(id);
  if(action==='plan')return showPlan(id);
  if(action==='start-plan'){const p=PLANS.find(p=>p.id===id);return startTraining(p.exerciseIds,p.name);}
  if(action==='select-exercise'){state.selected.has(id)?state.selected.delete(id):state.selected.add(id);return render();}
  if(action==='clear-selection'){state.selected.clear();return render();}
  if(action==='start-selected')return startTraining([...state.selected]);
  if(action==='add-one'){if(s)return startTraining([id]);state.selected.add(id);closeModal();navigate('train');return toast('已加入待练动作');}
  if(action==='cardio-only'){await startTraining([],'有氧训练');return cardioForm();}
  if(action==='cardio'){if(!s)await startTraining([],'有氧训练');return cardioForm();}
  if(action==='edit-cardio'){return cardioForm(s.cardio.find(c=>c.id===id));}
  if(action==='remove-cardio'){s.cardio=s.cardio.filter(c=>c.id!==id);await saveNow();return render();}
  if(action==='toggle-pause'){if(s.runningSince){s.elapsedSeconds=elapsed(s);s.runningSince=null;s.restEndsAt=null;}else s.runningSince=Date.now();await saveNow();return render();}
  if(action==='retry-save')return saveNow().then(()=>toast('训练进度已保存'));
  if(action==='rest'){if(s.restEndsAt)s.restEndsAt=null;else{s.restEndsAt=Date.now()+state.profile.restSeconds*1000;restNotified=false;}await saveNow();return render();}
  if(action==='add-set'){const e=s.exercises.find(e=>e.id===id);e.sets.push(createSet(e.sets.at(-1)||{reps:e.unit==='seconds'?30:10}));await saveNow();return render();}
  if(action==='set-done'){const table=el.closest('.set-table');if([...table.querySelectorAll('input')].some(input=>input.value===''||!input.validity.valid)){toast('请先核对本动作的重量和次数');return;}const e=s.exercises.find(e=>e.id===el.dataset.exercise),set=e.sets.find(t=>t.id===id);if(Number(set.reps)<=0||!Number.isFinite(Number(set.reps))){toast('先填写有效的次数或时长');return;}set.done=!set.done;if(set.done&&s.runningSince){s.restEndsAt=Date.now()+state.profile.restSeconds*1000;restNotified=false;}await saveNow();return render();}
  if(action==='remove-set'){const e=s.exercises.find(e=>e.id===el.dataset.exercise);if(e.sets.length===1){toast('每个动作至少保留一组，或删除整个动作');return;}e.sets=e.sets.filter(t=>t.id!==id);await saveNow();return render();}
  if(action==='remove-exercise'){const e=s.exercises.find(e=>e.id===id);return modal('移除这个动作？',`<p class="modal-subtitle">${esc(e.name)}及本次已填的组数会从草稿中移除。</p><div class="form-actions"><button class="button soft" data-action="close-modal">保留</button><button class="button danger" data-action="confirm-remove-exercise" data-id="${id}">移除动作</button></div>`);}
  if(action==='confirm-remove-exercise'){s.exercises=s.exercises.filter(e=>e.id!==id);await saveNow();closeModal();return render();}
  if(action==='edit-title')return modal('给这次训练起个名字',`<form id="title-form"><label class="form-field">训练名称<input name="title" value="${esc(titleFor(s))}" required maxlength="60"></label><div class="form-actions"><button class="button lime" type="submit">保存</button></div></form>`);
  if(action==='feeling'){s.feeling=s.feeling===el.dataset.value?'':el.dataset.value;await saveNow();return render();}
  if(action==='finish')return finishDialog();
  if(action==='discard')return modal('删除这次未完成的训练？',`<div class="notice">本次草稿中的组数、照片和笔记都会一并删除。</div><div class="form-actions"><button class="button soft" data-action="close-modal">继续保留</button><button class="button danger" data-action="confirm-discard">删除草稿</button></div>`);
  if(action==='confirm-discard'){await replaceData(()=>db.deleteSession(s.id));navigate('home');return toast('草稿已删除');}
  if(action==='history-period'){state.historyPeriod=el.dataset.value;state.historyDay=null;return render();}
  if(action==='calendar-day'){state.historyDay=el.dataset.date;return render();}
  if(action==='clear-history-day'){state.historyDay=null;return render();}
  if(action==='month'){state.calendar=new Date(state.calendar.getFullYear(),state.calendar.getMonth()+Number(el.dataset.delta),1);return render();}
  if(action==='record')return showRecord(id);
  if(action==='edit-record')return editRecord(id);
  if(action==='repeat-record'){const old=state.sessions.find(s=>s.id===id);return startTraining(old.exercises.map(e=>e.exerciseId),old.title||titleFor(old));}
  if(action==='delete-record')return modal('删除这次训练？',`<p class="modal-subtitle">训练与关联照片会一起删除，统计会同步更新。</p><div class="form-actions"><button class="button soft" data-action="record" data-id="${id}">取消</button><button class="button danger" data-action="confirm-delete-record" data-id="${id}">删除训练</button></div>`);
  if(action==='confirm-delete-record'){const r=state.sessions.find(s=>s.id===id);r?.photoIds?.forEach(releasePhotoURLs);await db.deleteSession(id);await refreshData();closeModal();render();return toast('训练与照片已删除');}
  if(action==='learn-exercise'){const e=getExercise(id)||state.sessions.flatMap(s=>s.exercises||[]).find(e=>e.exerciseId===id);if(!e)return toast('请先输入要搜索的动作名称');state.tutorialQuery=e.name+' '+e.equipment+' 动作教学';return navigate('learn');}
  if(action==='platform-search')return searchPlatform(el.dataset.platform);
  if(action==='keyword'){state.tutorialQuery=el.dataset.query;return render();}
  if(action==='copy-query'){const q=queryValue();if(!q)return toast('先输入搜索词');try{await navigator.clipboard.writeText(q);toast('搜索词已复制，到平台粘贴即可');}catch{modal('复制搜索词',`<input value="${esc(q)}" style="width:100%" readonly aria-label="搜索词"><p class="inline-note">长按输入框，选择复制。</p>`);}return;}
  if(action==='add-favorite')return favoriteForm();
  if(action==='delete-favorite')return modal('移除这条教学收藏？',`<p class="modal-subtitle">只移除PingFit中的链接，不会修改原平台内容。</p><div class="form-actions"><button class="button soft" data-action="close-modal">保留</button><button class="button danger" data-action="confirm-delete-favorite" data-id="${id}">移除</button></div>`);
  if(action==='confirm-delete-favorite'){await db.deleteFavorite(id);await refreshData();closeModal();return render();}
  if(action==='add-photos'||action==='add-record-photos'){if(!s&&!id)return toast('先开始训练，再添加照片');currentRecordId=id||s.id;$('#photo-input').click();return;}
  if(action==='view-photo'){const p=await db.getPhoto(id);if(!p)return;const key=p.id+':full';if(!state.photoUrls.has(key))state.photoUrls.set(key,URL.createObjectURL(p.blob));return modal('训练照片',`<img class="photo-full" src="${state.photoUrls.get(key)}" alt="${esc(p.name)}"><p class="inline-note">${esc(p.name)} · ${esc(dateLabel(p.createdAt))}</p><button class="button soft full" style="margin-top:18px" data-action="record" data-id="${p.sessionId}">返回训练记录</button>`,'photo');}
  if(action==='remove-photo')return modal('删除这张照片？',`<p class="modal-subtitle">照片将从本机训练记录中移除。</p><div class="form-actions"><button class="button soft" data-action="close-modal">保留</button><button class="button danger" data-action="confirm-remove-photo" data-id="${id}" data-session="${el.dataset.session}">删除照片</button></div>`);
  if(action==='confirm-remove-photo'){await saveNow();await db.deletePhoto(id);releasePhotoURLs(id);await refreshData();closeModal();render();return toast('照片已删除');}
  if(action==='recognize')return state.recognition?showRecognition():recognitionIntro();
  if(action==='pick-recognition'){$('#recognize-input').click();return;}
  if(action==='apply-recognition'){const r=state.recognition;if(!r)return;if(!s)await startTraining([],'有氧训练');return cardioForm({},r.fields,r);}
  if(action==='apply-strength-recognition')return strengthRecognition();
  if(action==='export-backup')return exportData();
  if(action==='share-backup'){try{await navigator.share({files:[state.exportFile],title:'PingFit完整备份'});}catch(e){if(e.name!=='AbortError')toast('系统分享未完成，请使用下载备份');}return;}
  if(action==='import-backup'){$('#backup-input').click();return;}
  if(action==='confirm-import'){const backup=validateAppBackup(state.pendingBackup);await replaceData(()=>db.importBackup(backup));state.pendingBackup=null;state.profile=normalizeProfile(await db.getSetting('profile',{}));recognitionJob++;state.recognition=null;cardioContext=null;strengthContext=null;for(const u of state.photoUrls.values())URL.revokeObjectURL(u);state.photoUrls.clear();closeModal();render();return toast('备份已恢复');}
  if(action==='clear-data')return modal('清除所有本机数据？',`<div class="notice">所有训练、照片、设置和教程收藏将被删除。请先导出备份。</div><div class="form-actions"><button class="button soft" data-action="close-modal">保留数据</button><button class="button danger" data-action="confirm-clear">确认清除全部</button></div>`);
  if(action==='confirm-clear'){await replaceData(()=>db.clearAllData());state.profile=normalizeProfile({});recognitionJob++;state.recognition=null;cardioContext=null;strengthContext=null;for(const u of state.photoUrls.values())URL.revokeObjectURL(u);state.photoUrls.clear();navigate('home');return toast('本机数据已清除');}
}

document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;event.preventDefault();if('disabled'in el)el.disabled=true;const action=el.dataset.action;Promise.resolve(handleAction(action,el)).catch(error=>{console.error(error);toast(error.message||'操作未完成，请重试');}).finally(()=>{if(el.isConnected)el.disabled=false;});});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='exercise-search'){state.search=el.value;const start=el.selectionStart;render();const input=$('#exercise-search');input.focus();input.setSelectionRange(start,start);return;}if(el.dataset.setInput&&state.active&&!storageBusy&&!state.readOnly){const e=state.active.exercises.find(e=>e.id===el.dataset.exercise),t=e?.sets.find(t=>t.id===el.dataset.id);if(!t)return;const value=Number(el.value);if(el.value!==''&&el.validity.valid&&Number.isFinite(value)&&value>=(el.dataset.setInput==='reps'?1:0)){t[el.dataset.setInput]=Math.min(el.dataset.setInput==='weight'?2000:3600,value);scheduleSave();updateLive();}}if(el.id==='workout-notes'&&state.active&&!storageBusy&&!state.readOnly){state.active.notes=el.value.slice(0,10000);scheduleSave();}if(el.id==='tutorial-query')state.tutorialQuery=el.value;});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='progress-exercise'){state.progressExercise=el.value;render();}if(el.id==='photo-input'){const files=[...el.files];el.value='';attachPhotos(files,currentRecordId).catch(e=>toast(e.message));}if(el.id==='recognize-input'){const file=el.files[0];el.value='';if(file)recognizeFile(file);}if(el.id==='backup-input'){const file=el.files[0];el.value='';if(file)importData(file).catch(e=>toast('无法恢复：'+e.message));}});
document.addEventListener('submit',async event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;event.preventDefault();if(!form.reportValidity())return;if((storageBusy||state.readOnly)&&form.id!=='learn-search-form'){toast('当前窗口暂时无法写入，请稍后重试。');return;}const button=form.querySelector('[type="submit"]');if(button)button.disabled=true;const data=Object.fromEntries(new FormData(form));try{
  if(form.id==='settings-form'){state.profile=normalizeProfile({...state.profile,name:data.name.trim()||'Cong',weight:Number(data.weight),weightConfirmed:true,weeklyGoal:Number(data.weeklyGoal),restSeconds:Number(data.restSeconds)});await db.setSetting('profile',state.profile);if(state.active&&!state.active.weightKg){state.active.weightKg=state.profile.weight;await saveNow();}closeModal();render();toast('个人设置已保存');}
  if(form.id==='title-form'){state.active.title=data.title.trim();await saveNow();closeModal();render();}
  if(form.id==='cardio-form'){const context=cardioContext;if(!context)throw new Error('请重新打开有氧记录');if(!state.active)await startTraining([],'有氧训练');const s=state.active;if(context.sessionId&&context.sessionId!==s.id)throw new Error('训练已变更，请重新添加有氧记录。');const item={id:context.id,typeId:data.typeId,minutes:Number(data.minutes),distance:data.distance===''?null:Number(data.distance),kcal:data.kcal===''?null:Number(data.kcal),caloriesSource:data.kcal===''?'estimate':'device',intensity:data.intensity};const at=s.cardio.findIndex(c=>c.id===item.id);if(at>=0)s.cardio[at]=item;else s.cardio.push(item);await saveNow();if(context.recognition?.prepared){const p=context.recognition.prepared;await db.savePhoto({...p,id:context.photoId,sessionId:s.id,createdAt:new Date().toISOString(),kind:'screen'});if(state.recognition?.job===context.recognition.job)state.recognition=null;}cardioContext=null;await refreshData();closeModal();navigate('workout');toast('有氧记录已保存');}
  if(form.id==='recognition-strength-form'){const context=strengthContext;if(!context)throw new Error('请重新打开力量识别结果。');if(!state.active)await startTraining([data.exerciseId]);const s=state.active;let exercise=s.exercises.find(e=>e.exerciseId===data.exerciseId);if(!exercise){exercise=createSession([data.exerciseId],state.profile).exercises[0];s.exercises.push(exercise);}const recorded={id:context.id,weight:Number(data.weight),reps:Number(data.reps),done:true};const existing=exercise.sets.findIndex(t=>t.id===context.id);if(existing>=0)exercise.sets[existing]=recorded;else{const blank=exercise.sets.findIndex(t=>!t.done&&Number(t.weight)===0);if(blank>=0)exercise.sets[blank]=recorded;else exercise.sets.push(recorded);}await saveNow();await db.savePhoto({...context.recognition.prepared,id:context.photoId,sessionId:s.id,kind:'screen',createdAt:new Date().toISOString()});if(state.recognition?.job===context.recognition.job)state.recognition=null;strengthContext=null;await refreshData();closeModal();navigate('workout');toast('已保存确认的一组训练与照片');}
  if(form.id==='finish-form'){const active=state.active;if(!active||finishing)return;const minutes=Number(data.minutes),cardio=active.cardio.reduce((n,c)=>n+Number(c.minutes||0),0);if(minutes+.01<cardio)throw new Error('总运动时长不能小于已录入的有氧时长。');clearTimeout(saveTimer);finishing=true;try{await saveQueue.catch(()=>{});const s={...structuredClone(active),title:data.title.trim(),notes:data.notes,feeling:data.feeling,elapsedSeconds:minutes*60,runningSince:null,restEndsAt:null,endedAt:new Date().toISOString(),status:'completed'};await queueSave(s);state.active=null;await refreshData();navigate('history');await showRecord(s.id);toast('这次认真，已经记下来了');}finally{finishing=false;}}
  if(form.id==='edit-record-form'){const s=structuredClone(state.sessions.find(s=>s.id===editingId));if(!s)throw new Error('记录不存在');const minutes=Number(data.minutes);s.cardio=s.cardio.map((c,i)=>({...c,typeId:data[`ct_${i}`],minutes:Number(data[`cm_${i}`]),distance:data[`cd_${i}`]===''?null:Number(data[`cd_${i}`]),kcal:data[`ck_${i}`]===''?null:Number(data[`ck_${i}`]),caloriesSource:data[`ck_${i}`]===''?'estimate':'manual'}));if(minutes+.01<s.cardio.reduce((n,c)=>n+Number(c.minutes||0),0))throw new Error('总运动时长不能小于有氧时长。');s.title=data.title.trim();s.startedAt=new Date(data.date+'T12:00:00').toISOString();s.elapsedSeconds=minutes*60;s.endedAt=new Date(new Date(s.startedAt).getTime()+minutes*60000).toISOString();s.notes=data.notes;s.exercises.forEach((e,i)=>e.sets.forEach((t,j)=>{t.weight=Number(data[`w_${i}_${j}`]);t.reps=Number(data[`r_${i}_${j}`]);t.done=data[`d_${i}_${j}`]==='on';}));await db.saveSession(s);await refreshData();render();await showRecord(s.id);toast('记录与统计已更新');}
  if(form.id==='favorite-form'){const match=data.url.match(/https?:\/\/[^\s<>"“”]+/i);if(!match)throw new Error('请粘贴包含 http 或 https 地址的分享链接');const url=new URL(match[0].replace(/[，。；、！!?）)]+$/,''));if(!['https:','http:'].includes(url.protocol))throw new Error('链接格式不正确');await db.saveFavorite({id:uid(),title:data.title.trim(),url:url.href,platform:/xiaohongshu|xhslink/.test(url.hostname)?'xhs':/douyin|iesdouyin/.test(url.hostname)?'douyin':'other',exerciseId:data.exerciseId,createdAt:new Date().toISOString()});await refreshData();closeModal();navigate('learn');toast('教程已收藏');}
  if(form.id==='learn-search-form'){state.tutorialQuery=data.query.trim();modal('选择搜索平台',`<p class="modal-subtitle">${esc(state.tutorialQuery)}</p><div class="platform-buttons"><button class="platform-button" data-action="platform-search" data-platform="douyin"><span class="platform-mark">♪</span>抖音 ${icon('arrow')}</button><button class="platform-button" data-action="platform-search" data-platform="xhs"><span class="platform-mark red">小红书</span>小红书 ${icon('arrow')}</button></div><p class="inline-note">会打开原平台搜索页；如果无法跳转，请复制搜索词到平台内搜索。</p>`,'search-platform');}
}catch(error){console.error(error);toast(error.message||'保存未完成，请重试');}finally{if(button?.isConnected)button.disabled=false;}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=$('#modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
$('#modal').addEventListener('cancel',()=>{state.modalKind='';});
window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);state.route=['home','train','history','learn','workout'].includes(route)?route:'home';render();});
window.addEventListener('online',()=>{state.offline=false;render();});window.addEventListener('offline',()=>{state.offline=true;render();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.active)saveNow().catch(()=>{});});
window.addEventListener('pagehide',()=>{if(state.active)saveNow().catch(()=>{});});

async function boot(){try{await db.initDB();await takeWriteLock();state.profile=normalizeProfile(await db.getSetting('profile',{}));await refreshData();state.route=['home','train','history','learn','workout'].includes(location.hash.slice(1))?location.hash.slice(1):'home';render();if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js').then(reg=>{if(reg.waiting)toast('新版已准备好，下次重新打开即可更新');reg.addEventListener('updatefound',()=>{const worker=reg.installing;worker?.addEventListener('statechange',()=>{if(worker.state==='installed'&&!navigator.serviceWorker.controller)toast('离线资源已准备好，可以添加到主屏幕了');});});}).catch(()=>{});}}catch(error){$('#content').innerHTML=`<div class="fatal"><h2>暂时无法打开本地记录</h2><p>${esc(error.message)}<br>请检查 Safari 的存储空间与浏览设置后重新打开。已有备份可以在恢复正常后导入。</p><button class="button" data-action="reload">重新打开</button></div>`;document.querySelector('[data-action="reload"]')?.addEventListener('click',()=>location.reload());}}
boot();
